function DIVIDES_VALUE(u, p, m, rank = NONE):
    if rank = NONE:
        rank <- APPARITION_RANK(u, p)
    return (m mod rank = 0)   # law of apparition: p|u(m) <=> rank|m

function JOINT_APPARITION(u, data = [(p_1, r_1), ..., (p_k, r_k)], N):
    period <- 1
    for (p_i, r_i) in data:
        period <- LCM(period, r_i)
    count <- floor(N / period) if period > 0 else 0
    return (period, count)
